INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00592','seven-eleven-hourglasses-second-flip-fifteen','az','Məntiq və düşünmə','çətin','7 və 11 dəqiqəlik qum saatları eyni anda başladılır. 7 dəqiqəlik saat bitəndə çevrilir. 11 dəqiqəlik bitəndə 7 dəqiqəlik yenə çevrilir. Son çevrilmədən sonra bitəndə başlanğıcdan neçə dəqiqə keçib?','{"A":"18","B":"21","C":"14","D":"15"}','D','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"7-ci dəqiqədə çevrilən saatın 11-ci dəqiqədə altına 4 dəqiqəlik qum düşüb; yenidən çevriləndə 4 dəqiqədə bitir. 11+4=15."}','review_ready','{"id":"AZQ-00592","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"seven-eleven-hourglasses-second-flip-fifteen","question":"7 və 11 dəqiqəlik qum saatları eyni anda başladılır. 7 dəqiqəlik saat bitəndə çevrilir. 11 dəqiqəlik bitəndə 7 dəqiqəlik yenə çevrilir. Son çevrilmədən sonra bitəndə başlanğıcdan neçə dəqiqə keçib?","options":{"A":"18","B":"21","C":"14","D":"15"},"correctOption":"D","correctAnswer":"15","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"7-ci dəqiqədə çevrilən saatın 11-ci dəqiqədə altına 4 dəqiqəlik qum düşüb; yenidən çevriləndə 4 dəqiqədə bitir. 11+4=15."},"status":"review_ready","batch":"batch-013.txt","contentHash":"cf668d302897c7604cf15c2d7c23a14eea217e52beccdb4c7adcf109c090db34"}','cf668d302897c7604cf15c2d7c23a14eea217e52beccdb4c7adcf109c090db34') ON CONFLICT (id) DO NOTHING;
