INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00641','three-hats-two-black-one-white-inference','az','Məntiq və düşünmə','çətin','Üç papaqdan ikisi qara, biri ağdır. Sayı bilən iki nəfərin hərəsinə bir papaq qoyulur. Bir-birini görürlər. Aysel dürüstcə öz rəngini bilmədiyini deyir. Bunu eşidən Murad öz papağını müəyyən edir. Muradın papağı nə rəngdir?','{"A":"Ağ","B":"Hər iki rəng ola bilər","C":"Qara","D":"Papaqsızdır"}','C','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"Murad ağ olsaydı Aysel özünün qara olduğunu bilərdi; bilməməsi Muradın qara olduğunu göstərir."}','review_ready','{"id":"AZQ-00641","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"three-hats-two-black-one-white-inference","question":"Üç papaqdan ikisi qara, biri ağdır. Sayı bilən iki nəfərin hərəsinə bir papaq qoyulur. Bir-birini görürlər. Aysel dürüstcə öz rəngini bilmədiyini deyir. Bunu eşidən Murad öz papağını müəyyən edir. Muradın papağı nə rəngdir?","options":{"A":"Ağ","B":"Hər iki rəng ola bilər","C":"Qara","D":"Papaqsızdır"},"correctOption":"C","correctAnswer":"Qara","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"Murad ağ olsaydı Aysel özünün qara olduğunu bilərdi; bilməməsi Muradın qara olduğunu göstərir."},"status":"review_ready","batch":"batch-014.txt","contentHash":"5c1a2b9cf20cd24547524eddcb4c01379551079b1afdbc20069b28a874b3a14f"}','5c1a2b9cf20cd24547524eddcb4c01379551079b1afdbc20069b28a874b3a14f') ON CONFLICT (id) DO NOTHING;
