INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00643','grid-three-east-two-north-path-count','az','Məntiq və düşünmə','çətin','Şəbəkədə başlanğıcdan sona getmək üçün 3 dəfə şərqə, 2 dəfə şimala addım atmalısan. Geri addım atmadan neçə fərqli addım ardıcıllığı var?','{"A":"12","B":"5","C":"6","D":"10"}','D','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"Beş addımın içində iki şimal mövqeyi seçilir: 5×4/2=10."}','review_ready','{"id":"AZQ-00643","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"grid-three-east-two-north-path-count","question":"Şəbəkədə başlanğıcdan sona getmək üçün 3 dəfə şərqə, 2 dəfə şimala addım atmalısan. Geri addım atmadan neçə fərqli addım ardıcıllığı var?","options":{"A":"12","B":"5","C":"6","D":"10"},"correctOption":"D","correctAnswer":"10","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"Beş addımın içində iki şimal mövqeyi seçilir: 5×4/2=10."},"status":"review_ready","batch":"batch-014.txt","contentHash":"2e9629635062e23b372d995dec88bfd21cd46bc1d11d553fc7dc3f170a533b5b"}','2e9629635062e23b372d995dec88bfd21cd46bc1d11d553fc7dc3f170a533b5b') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00644','two-eggs-ten-floors-minimax-four','az','Məntiq və düşünmə','çətin','Eyni iki sınaq topu müəyyən mərtəbədən başlayaraq qırılır; hədd 1–10 mərtəbələrdən biri və ya 10-dan yuxarıdır. Qırılmayan top yenidən işlədilir. Həddi tapmaq üçün ən pis halda minimum neçə atış lazımdır?','{"A":"4","B":"3","C":"5","D":"10"}','A','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"4 atışla 4+3+2+1=10 mərtəbə yoxlanır; 3 atışla ən çox 6 mərtəbə ayırd edilir."}','review_ready','{"id":"AZQ-00644","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"two-eggs-ten-floors-minimax-four","question":"Eyni iki sınaq topu müəyyən mərtəbədən başlayaraq qırılır; hədd 1–10 mərtəbələrdən biri və ya 10-dan yuxarıdır. Qırılmayan top yenidən işlədilir. Həddi tapmaq üçün ən pis halda minimum neçə atış lazımdır?","options":{"A":"4","B":"3","C":"5","D":"10"},"correctOption":"A","correctAnswer":"4","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"4 atışla 4+3+2+1=10 mərtəbə yoxlanır; 3 atışla ən çox 6 mərtəbə ayırd edilir."},"status":"review_ready","batch":"batch-014.txt","contentHash":"9509fcb2c3eca647b9dfb4d0ac39c746cc541abefa370edf9cc40014a5325a31"}','9509fcb2c3eca647b9dfb4d0ac39c746cc541abefa370edf9cc40014a5325a31') ON CONFLICT (id) DO NOTHING;
