INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00847','earth-rope-extra-metre-radius-gap','az','Məntiq və düşünmə','orta','Yer kürəsini ideal kürə sayaq. Ekvator boyu halqa şəklində ipi 1 metr uzadıb hər yerdə bərabər qaldırsaq, səthlə ip arasındakı boşluq təxminən nə qədər olar? π≈3,14.','{"A":"1 santimetr","B":"16 santimetr","C":"1 metr","D":"1 millimetr"}','B','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"2πr çevrə düsturuna görə radius artımı 1/(2×3,14)≈0,159 metrdir; əvvəlki radius nəticəyə təsir etmir."}','review_ready','{"id":"AZQ-00847","language":"az","category":"Məntiq və düşünmə","difficulty":"orta","difficultyStatus":"provisional","factKey":"earth-rope-extra-metre-radius-gap","question":"Yer kürəsini ideal kürə sayaq. Ekvator boyu halqa şəklində ipi 1 metr uzadıb hər yerdə bərabər qaldırsaq, səthlə ip arasındakı boşluq təxminən nə qədər olar? π≈3,14.","options":{"A":"1 santimetr","B":"16 santimetr","C":"1 metr","D":"1 millimetr"},"correctOption":"B","correctAnswer":"16 santimetr","points":20,"timeLimitSeconds":25,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"2πr çevrə düsturuna görə radius artımı 1/(2×3,14)≈0,159 metrdir; əvvəlki radius nəticəyə təsir etmir."},"status":"review_ready","batch":"batch-018.txt","contentHash":"92133517f5cc13f78fefe5eb1c0466ed0fdaceace567605bafa670810b5cede8"}','92133517f5cc13f78fefe5eb1c0466ed0fdaceace567605bafa670810b5cede8') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00848','red-blue-replacement-parity-invariant','az','Məntiq və düşünmə','çətin','Qutuda 5 qırmızı, 6 mavi daş var. Hər dəfə iki daş çıxarılır: eyni rəngdədirsə bir mavi, fərqlidirsə bir qırmızı qaytarılır. Bir daş qalanda rəngi nə olar?','{"A":"Hər iki rəng eyni ehtimallıdır","B":"Mütləq mavi","C":"Mütləq qırmızı","D":"Seçimdən asılı olaraq dəyişər"}','C','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"Qırmızıların sayı hər addımda 0 və ya 2 azalır; təkliyi dəyişmir. Tək qalan daşda qırmızı sayı tək olmalıdır, yəni 1-dir."}','review_ready','{"id":"AZQ-00848","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"red-blue-replacement-parity-invariant","question":"Qutuda 5 qırmızı, 6 mavi daş var. Hər dəfə iki daş çıxarılır: eyni rəngdədirsə bir mavi, fərqlidirsə bir qırmızı qaytarılır. Bir daş qalanda rəngi nə olar?","options":{"A":"Hər iki rəng eyni ehtimallıdır","B":"Mütləq mavi","C":"Mütləq qırmızı","D":"Seçimdən asılı olaraq dəyişər"},"correctOption":"C","correctAnswer":"Mütləq qırmızı","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"Qırmızıların sayı hər addımda 0 və ya 2 azalır; təkliyi dəyişmir. Tək qalan daşda qırmızı sayı tək olmalıdır, yəni 1-dir."},"status":"review_ready","batch":"batch-018.txt","contentHash":"787418aadd99234ce45f8c6bc60467191d7ea03f12c212d65a8a6ac43acd5e7f"}','787418aadd99234ce45f8c6bc60467191d7ea03f12c212d65a8a6ac43acd5e7f') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_bank.questions(id,fact_key,language,category,difficulty,question,options,correct_option,source,verification,status,payload,content_hash) VALUES ('AZQ-00849','milk-coffee-return-spoon-conservation','az','Məntiq və düşünmə','çətin','İki eyni həcmli qabda ayrı-ayrılıqda süd və qəhvə var. Qəhvədən bir qaşıq südə qatılıb qarışdırılır; qarışıqdan eyni həcmli qaşıq geri qaytarılır. Son həcmdə dəyişmə yoxdur. Hansı miqdar daha çoxdur?','{"A":"Nəticə yalnız ilk qaşığın həcmindən asılıdır","B":"Qəhvə qabındakı süd daha çoxdur","C":"Süd qabındakı qəhvə daha çoxdur","D":"Süd qabındakı qəhvə ilə qəhvə qabındakı süd bərabərdir"}','D','{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"}','{"method":"derivation","checkedAt":"2026-10-05","note":"Süd qabına x qədər qəhvə qalıbsa, ilk həcm bərpa edildiyinə görə onun yerini tutan x qədər süd o biri qabdadır; həcm qorunması yetərlidir."}','review_ready','{"id":"AZQ-00849","language":"az","category":"Məntiq və düşünmə","difficulty":"çətin","difficultyStatus":"provisional","factKey":"milk-coffee-return-spoon-conservation","question":"İki eyni həcmli qabda ayrı-ayrılıqda süd və qəhvə var. Qəhvədən bir qaşıq südə qatılıb qarışdırılır; qarışıqdan eyni həcmli qaşıq geri qaytarılır. Son həcmdə dəyişmə yoxdur. Hansı miqdar daha çoxdur?","options":{"A":"Nəticə yalnız ilk qaşığın həcmindən asılıdır","B":"Qəhvə qabındakı süd daha çoxdur","C":"Süd qabındakı qəhvə daha çoxdur","D":"Süd qabındakı qəhvə ilə qəhvə qabındakı süd bərabərdir"},"correctOption":"D","correctAnswer":"Süd qabındakı qəhvə ilə qəhvə qabındakı süd bərabərdir","points":30,"timeLimitSeconds":30,"sourceId":"CAL","source":{"url":null,"title":"Müəllifin hesablaması","section":"Sualın şərtlərindən çıxarılan həll"},"verification":{"method":"derivation","checkedAt":"2026-10-05","note":"Süd qabına x qədər qəhvə qalıbsa, ilk həcm bərpa edildiyinə görə onun yerini tutan x qədər süd o biri qabdadır; həcm qorunması yetərlidir."},"st